from collections import OrderedDict
from typing import List

def parse_query_string(query: str) -> List[str]:
    if query.startswith('?'):
        query = query[1:]
    od: "OrderedDict[str, List[str]]" = OrderedDict()
    if not query:
        return []
    for part in query.split('&'):
        if not part:
            continue
        if part.startswith('!'):
            k = part[1:]
            od.setdefault(k, []).append("true")
        elif '=' in part:
            k, v = part.split('=', 1)
            if v.startswith('"') and v.endswith('"'):
                v = v[1:-1]
            elif v.startswith('[') and v.endswith(']'):
                v = v[1:-1].replace(',', '|')
            od.setdefault(k, []).append(v)
    return [f"{k}={'|'.join(vs)}" for k, vs in od.items()]

import java.util.*;

class Solution {
    public String[] parseQueryString(String query) {
        if (query.startsWith("?")) query = query.substring(1);
        Map<String, List<String>> od = new LinkedHashMap<>();
        if (query.isEmpty()) return new String[0];
        for (String part : query.split("&")) {
            if (part.isEmpty()) continue;
            if (part.startsWith("!")) {
                od.computeIfAbsent(part.substring(1), k -> new ArrayList<>()).add("true");
            } else {
                int eq = part.indexOf('=');
                if (eq < 0) continue;
                String k = part.substring(0, eq), v = part.substring(eq + 1);
                if (v.startsWith("\"") && v.endsWith("\"")) v = v.substring(1, v.length() - 1);
                else if (v.startsWith("[") && v.endsWith("]")) v = v.substring(1, v.length() - 1).replace(",", "|");
                od.computeIfAbsent(k, x -> new ArrayList<>()).add(v);
            }
        }
        List<String> out = new ArrayList<>();
        for (var e : od.entrySet()) out.add(e.getKey() + "=" + String.join("|", e.getValue()));
        return out.toArray(new String[0]);
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<string> parseQueryString(string query) {
        if (!query.empty() && query.front() == '?') query.erase(0, 1);
        vector<string> keys;
        unordered_map<string, vector<string>> od;
        vector<string> parts; string cur;
        for (char c : query) { if (c == '&') { parts.push_back(cur); cur.clear(); } else cur += c; }
        if (!cur.empty()) parts.push_back(cur);
        for (auto& part : parts) {
            if (part.empty()) continue;
            string k, v;
            if (part[0] == '!') { k = part.substr(1); v = "true"; }
            else {
                auto eq = part.find('=');
                if (eq == string::npos) continue;
                k = part.substr(0, eq); v = part.substr(eq + 1);
                if (v.size() >= 2 && v.front() == '"' && v.back() == '"') v = v.substr(1, v.size() - 2);
                else if (v.size() >= 2 && v.front() == '[' && v.back() == ']') {
                    v = v.substr(1, v.size() - 2);
                    for (auto& c : v) if (c == ',') c = '|';
                }
            }
            if (!od.count(k)) keys.push_back(k);
            od[k].push_back(v);
        }
        vector<string> out;
        for (auto& k : keys) {
            string s = k + "=";
            for (size_t i = 0; i < od[k].size(); i++) { if (i) s += '|'; s += od[k][i]; }
            out.push_back(s);
        }
        return out;
    }
};
